{"path": "task.py", "content": "import math

def permutation_rank(*args, **kwargs):
    if args:
        perm = args[0]
    else:
        # fallback, maybe from kwargs
        perm = kwargs.get('perm')
    if not isinstance(perm, (list, tuple)):
        perm = list(perm)
    n = len(perm)
    sorted_elems = sorted(perm)
    rank = 0
    for i, x in enumerate(perm):
        count = sorted_elems.index(x)
        rank += count * math.factorial(n - i - 1)
        sorted_elems.remove(x)
    return rank
"}

